:root {
  --ink: #000000;
  --paper: #FFFFFF;
  --accent: #B54131;
  --border: #D6D6D6;
  --support: #555555;
  --radius: 5px;
  --space: 16px;
}

body { margin: 0; padding: 24px; background: var(--paper); color: var(--ink); font-family: "Noto Sans", sans-serif; }
.card { padding: var(--space); }
.cta { padding: 8px 12px; }
